export const MAIN_VIEW = { w: 596, h: 660 };
export const OKI_VIEW = { w: 48, h: 60 };

// 経緯度→本土図のpx座標
export function projectMain(lng: number, lat: number): [number, number] {
  return [
    (lng - 129) * 0.788011 * 44,
    (45.8 - lat) * 44,
  ];
}

// 経緯度→沖縄インセットのpx座標
export function projectOki(lng: number, lat: number): [number, number] {
  return [
    (lng - 127.5) * 0.894934 * 60,
    (27 - lat) * 60,
  ];
}

